import React from 'react'
type S={heading:string;text:string[]};type G={title:string;sections:S[]}
const guides:Record<string,G>={
"longevity-risk-calculator":{title:'Longevity Risk Calculator',sections:[{heading:'What this longevity model is—and is not',text:['This calculator combines age, sex, BMI, systolic blood pressure, smoking exposure, exercise, sleep, fruit and vegetable intake, alcohol, family history, chronic disease count, stress and social connection into a simplified life-expectancy adjustment. It begins from a fixed base life expectancy of 76 years for men and 81 for women, then adds or subtracts years according to the implemented rules.',"It is not an actuarial life table, clinical prognostic model or personalized prediction of age at death. The displayed projected life expectancy and years remaining are educational scenario outputs from this site's formula."]},{heading:'How the score is constructed',text:['BMI in the model can add two years when between 18.5 and 24.9, while higher BMI bands subtract years. Lower systolic blood pressure receives a positive adjustment and progressively higher readings receive larger deductions. Smoking pack-years can subtract between two and ten modeled years depending on exposure.','Exercise adds up to four years in the formula, seven to nine hours of sleep adds two, fruit and vegetable servings add up to two, heavy alcohol use subtracts years, family history subtracts two, each chronic disease subtracts 1.5, high stress subtracts years and strong social connection can add two.']},{heading:'Why age and population averages matter',text:["Life expectancy is a population statistic, not a countdown clock. Conditional life expectancy changes with current age: someone who has already reached an older age has survived risks that affected earlier cohorts. The site's fixed base values do not perform that full conditional-life-table calculation.",'Country, birth cohort, socioeconomic conditions and access to healthcare also affect population longevity. Treat the model as a lifestyle-risk illustration rather than a substitute for official life tables.']},{heading:'Smoking exposure',text:['Pack-years combine intensity and duration: roughly one pack per day for 20 years equals 20 pack-years, as does two packs per day for 10 years. The calculator uses broad pack-year bands because cumulative tobacco exposure is strongly associated with cardiovascular disease, cancer and chronic lung disease.',"Risk falls after smoking cessation, but it does not reset instantly to that of a never-smoker. The model's suggested '+4–10 years' is a simplified prompt, not a guaranteed benefit for an individual."]},{heading:'Blood pressure and cardiovascular risk',text:['Systolic blood pressure is one of the strongest modifiable inputs in this model. A single reading, however, can be distorted by stress, caffeine, pain, exercise or poor measurement technique. Clinical decisions usually rely on repeated properly taken readings or home/ambulatory monitoring.','Longevity risk is influenced by the whole cardiovascular profile—lipids, diabetes, kidney function and existing disease—not systolic pressure alone.']},{heading:'BMI and body composition',text:['BMI is a screening measure based on weight relative to height. It can be useful at population level but cannot distinguish fat mass from muscle or show fat distribution. The calculator therefore simplifies body-composition risk when it assigns fixed year adjustments to BMI categories.','Waist circumference, metabolic health, fitness and disease history can provide additional context. Avoid treating the exact BMI threshold as a sudden biological change in lifespan.']},{heading:'Exercise, sleep and diet',text:['The model rewards weekly exercise, adequate sleep and fruit/vegetable intake because these behaviors are associated with health outcomes. Benefits are not literally linear year credits in real life. Exercise type, intensity, cardiorespiratory fitness, resistance training and sedentary time all matter beyond weekly hours.','Likewise, diet quality cannot be reduced to produce servings. Protein quality, whole grains, fiber, sodium, ultra-processed food and total energy balance are not directly modeled.']},{heading:'Alcohol, stress and social connection',text:['The calculator penalizes higher weekly alcohol intake and high stress while rewarding stronger social connection. These factors can interact with sleep, mental health, cardiovascular risk and health behaviors. A single weekly drink count or 1–10 stress score cannot capture those pathways completely.','For alcohol, lower exposure generally reduces alcohol-attributable risk. Do not interpret a lack of penalty at lower values as a recommendation to drink for longevity.']},{heading:'Chronic disease and family history',text:['Each chronic disease receives the same deduction in the formula, although real conditions differ enormously in severity, treatment and prognosis. Controlled hypertension and advanced heart failure clearly should not carry identical prognostic weight.','Family history can signal inherited susceptibility and shared environment, but it does not determine destiny. Preventive care and management of measurable risk factors remain important even when family history is unfavorable.']},{heading:'Healthy years output',text:["The calculator estimates 'healthy years' as 85% of remaining years when BMI is below 30 and chronic disease count is below two, otherwise 70%. This is a simple rule, not a validated health-adjusted life expectancy calculation.",'Healthspan and lifespan are related but different goals. Maintaining mobility, cognition, independence and disease control can matter as much as maximizing a modeled age.']},{heading:'How to use the calculator responsibly',text:['Use the tool to compare modifiable scenarios: smoking cessation, better blood-pressure control, more activity or improved sleep. Change one factor at a time to see how this particular formula responds, but do not interpret the change as a medically guaranteed number of years gained.','For actual prevention decisions, prioritize evidence-based screening, vaccination, blood-pressure and lipid management, diabetes care, tobacco cessation, physical activity, sleep and clinician guidance appropriate to age and history.']}]},
"posture-assessment-calculator":{title:'Posture Assessment Calculator',sections:[{heading:'What the posture score represents',text:['This calculator converts forward-head distance, shoulder rounding, pelvic tilt, knee valgus, flat feet, daily sitting and years of desk work into a 0–100 posture score. In the implementation, a higher score means more modeled postural issues; it is not a clinical percentage of injury, disability or spinal damage.','Posture is variable rather than a single permanently correct position. People naturally shift positions throughout the day, and many visible deviations occur in people without pain.']},{heading:'How the implemented score works',text:['Forward-head distance receives twice its entered value, shoulder rounding 1.5 times its value, non-neutral pelvic tilt adds two points, knee valgus adds two and flat feet add one. Sitting beyond six hours adds 0.5 per extra hour, while years of office work add up to five points. The total is multiplied by five and capped at 100.','The categories are good posture below 20, mild deviations from 20, moderate issues from 45 and poor posture from 70. These are thresholds created for this tool, not validated diagnostic cutoffs.']},{heading:'Forward head position',text:['Forward-head posture describes the head sitting anterior to the trunk reference line. Screen height, vision, fatigue and habitual position can influence it. The calculator flags values above two centimeters as an issue and suggests chin tucks among its corrective ideas.','A photograph can exaggerate or hide the measurement depending on camera angle. If tracking change, use the same stance, camera height and landmark method each time.']},{heading:'Rounded shoulders',text:['Shoulder position reflects the thoracic spine, scapulae, chest musculature and task demands. The tool increases its score as shoulder rounding increases and suggests face pulls as one possible exercise.','No single exercise universally fixes shoulder symptoms. Strength, mobility, load tolerance and the actual source of pain matter more than forcing the shoulders into a rigid position all day.']},{heading:'Pelvic tilt',text:['The calculator distinguishes anterior, neutral and posterior pelvic tilt and adds the same penalty for either non-neutral option. In real anatomy, pelvic orientation varies with stance, hip shape, muscle activity and spinal curvature, and a visible tilt is not automatically pathological.','If pelvic position is associated with pain or functional limitation, assessment should focus on movement and symptoms rather than appearance alone.']},{heading:'Knee valgus and flat feet',text:['Knee valgus means the knees move inward relative to the hips and feet. It may appear during standing, squatting, landing or running and can be influenced by hip control, foot position and anatomy. Flat feet or pronation can also be normal variants, especially when flexible and painless.','The calculator adds fixed points for these observations, but it does not measure dynamic movement quality, strength or joint structure.']},{heading:'Sitting and desk work',text:['Hours seated above six and years of office work raise the score because prolonged static work can contribute to stiffness and discomfort. Sitting itself is not a diagnosis. The practical target is usually more movement variety: changing position, standing periodically, walking and arranging the workstation so common tasks do not require sustained strain.',"The tool's suggestion to stand or walk every 30–45 minutes is best understood as a movement prompt rather than a strict medical rule."]},{heading:'Ergonomic setup',text:['Place frequently viewed content near eye level, keep input devices within comfortable reach and support the feet when needed. Screen distance should allow relaxed viewing without repeatedly leaning forward. Laptop-only setups often benefit from an external keyboard or elevated display for longer sessions.','Ergonomics should fit the person and task. A theoretically perfect setup that forces one static posture for hours can still become uncomfortable.']},{heading:'Pain and posture are not the same thing',text:["The calculator labels pain risk as high when its posture score exceeds 60, but pain is multifactorial. Sleep, stress, workload, previous injury, physical capacity and sensitization can influence symptoms. Research does not support the idea that one universal 'bad posture' explains most neck and back pain.",'Do not interpret a high score as evidence that tissue is damaged, and do not interpret a low score as proof that persistent pain is harmless.']},{heading:'Using corrective exercise intelligently',text:['Chin tucks, face pulls, hip-flexor stretching and glute activation can be useful for some people because they provide movement and strengthen underused ranges. Progress should be based on comfort, control and function rather than trying to force the body into an idealized silhouette.','A balanced program may also include upper-back strength, shoulder rotation, trunk endurance, hip strength, walking and task-specific conditioning.']},{heading:'When professional assessment matters',text:['Seek assessment when posture concerns accompany persistent or severe pain, progressive weakness, numbness, balance problems, bowel/bladder changes, significant trauma or symptoms that worsen despite reasonable activity modification.','For routine desk discomfort, the most useful use of this calculator is as a checklist of observable habits and a baseline for experimenting with movement breaks and workstation changes—not as a medical diagnosis.']}]},
"responsive-breakpoints":{title:'Responsive Breakpoints',sections:[{heading:'What a breakpoint actually controls',text:['A responsive breakpoint is the viewport width at which a stylesheet changes layout rules. It is not a device detector: a 768 px breakpoint does not mean “tablet,” because browser windows, zoom, split-screen modes and high-density displays break that assumption. The useful question is where the current layout stops working comfortably.','Choose breakpoints from the content and component behavior. If a navigation bar wraps at 860 px, that is evidence for a breakpoint near that width even if a framework ships with a different preset.']},{heading:'Mobile-first media queries',text:['Mobile-first CSS starts with the narrowest usable layout and adds enhancements with min-width media queries. This reduces overrides because the base rules remain valid at larger sizes until a component genuinely needs more space.','Desktop-first max-width queries can work, but mixing both directions casually often creates overlapping rules and hard-to-debug cascade behavior.']},{heading:'CSS pixels and viewport width',text:['Media queries use CSS pixels, not the physical pixel count advertised by a phone or monitor. Device pixel ratio maps multiple hardware pixels to one CSS pixel, so a 1170-pixel phone panel may expose a viewport only a few hundred CSS pixels wide.','Test the actual CSS viewport and remember that browser chrome, orientation and embedded contexts can change the available width.']},{heading:'Common breakpoint ranges',text:['Framework defaults such as 640, 768, 1024 and 1280 px are convenient starting points, not universal truths. They work best when they coincide with real layout transitions in your design.','A site may need only two breakpoints while a dense dashboard may need several component-specific transitions. Fewer meaningful breakpoints are usually easier to maintain than many arbitrary ones.']},{heading:'Container queries',text:['Viewport breakpoints are insufficient when a reusable card can appear in a narrow sidebar or a wide main column. Container queries let a component respond to the size of its containing block rather than the entire browser window.','Use container queries for truly reusable components and viewport media queries for page-level changes such as global navigation or major grid structure.']},{heading:'Typography and fluid sizing',text:['Not every responsive change needs a hard breakpoint. clamp(), min(), max(), flexible grid tracks and relative units can make type, spacing and columns scale smoothly between limits.','Breakpoints are most valuable for structural changes: switching column count, moving navigation, changing alignment or hiding nonessential controls.']},{heading:'Images and media',text:['Responsive layouts also need responsive assets. Use max-width:100% for intrinsic media where appropriate, preserve aspect ratio, and use srcset/sizes or the framework image component so small screens do not download unnecessarily large images.','A breakpoint that fixes the grid but leaves a fixed-width image overflowing has not solved the responsive problem.']},{heading:'Testing strategy',text:['Drag-resizing a desktop browser is useful but incomplete. Test representative widths around every breakpoint, not only exactly at the threshold, and check portrait/landscape, zoom, long text, localization and browser font scaling.','DevTools device presets accelerate testing, but real devices remain useful for touch targets, browser UI, safe areas and performance.']},{heading:'Accessibility at breakpoints',text:['Responsive changes must preserve keyboard order, focus visibility and readable zoom. Avoid visually reordering content in a way that makes keyboard or screen-reader order confusing.','Do not disable user zoom to make a layout fit. Fix overflow, use flexible dimensions and ensure interactive targets remain usable on narrow screens.']},{heading:'How to use this tool',text:['Use the generator as a starting point for media-query syntax and breakpoint planning. Then inspect the actual component at widths just below and above each generated value.','The best breakpoint set is the smallest set that keeps content readable, controls usable and layouts stable across the widths your users actually encounter.']}]},
"salary-hike-calculator":{title:'Salary Hike Calculator',sections:[{heading:'What the salary hike calculation answers',text:['A salary hike changes more than the next paycheck. This calculator measures the immediate raise, projects future salary when subsequent annual hikes continue, adjusts the projected salary for inflation, and estimates the cumulative earnings advantage over a no-initial-hike baseline.','The key comparison is controlled: both paths receive the same future annual hike assumption, while only one path receives the initial hike entered today. That isolates the long-run value of the current raise within the model.']},{heading:'How the implemented model works',text:['New salary equals current salary multiplied by one plus the hike percentage. For each projected year, the new salary is compounded by the annual hike assumption. The calculator also constructs a baseline beginning from the old salary and compounding at that same annual rate, then subtracts baseline cumulative earnings from the raised path to produce lifetime gain.','Inflation is used to show real salary purchasing power. It does not reduce the nominal salary paid by the employer; it changes what that salary may buy.']},{heading:'Worked example',text:["If current salary is $60,000 and the immediate hike is 10%, the new salary is $66,000 and the first-step increase is $6,000. If both the raised path and baseline subsequently grow 4% annually, the initial $6,000 difference also compounds. Over several years the cumulative earnings advantage becomes much larger than one year's raise.",'If inflation is also 4%, nominal salary can keep rising while real purchasing power changes far less. This is why a headline raise should be evaluated against inflation as well as the percentage printed in an offer letter.']},{heading:'Raise percentage versus absolute money',text:['A percentage is easy to compare, but household decisions are made with currency. A 10% raise on $40,000 is $4,000; the same percentage on $100,000 is $10,000. Translate the result into monthly gross pay before judging its practical effect.','For negotiation, consider both the percentage relative to current pay and the resulting salary relative to the market range for the role, location and level.']},{heading:'Inflation and real salary',text:['A raise above inflation generally increases purchasing power before taxes and other changes. A raise equal to inflation roughly preserves purchasing power under the simplified model, while a raise below inflation can still leave real compensation lower despite a larger nominal paycheck.','Personal inflation can differ from published inflation. Rent, commuting, childcare or healthcare may dominate your budget, so use the inflation field as a scenario input rather than an unquestionable forecast.']},{heading:'Promotions, merit raises and market adjustments',text:['Not all hikes mean the same thing. A promotion may bring broader responsibilities and a new market band. A merit increase rewards performance within the same level. A market adjustment corrects pay relative to external or internal benchmarks. A cost-of-living adjustment is intended primarily to protect purchasing power.','When comparing offers or negotiating, identify which type of increase is being discussed because it affects what a reasonable benchmark looks like.']},{heading:'Total compensation matters',text:['The calculator models salary, not the full compensation package. Bonus target, commission, equity, employer retirement contributions, health insurance, paid leave and other benefits can outweigh a modest salary difference. A higher base may also increase benefits that are calculated as a percentage of salary.','For job-change decisions, compare total expected compensation and the probability of receiving variable pay, not salary alone.']},{heading:'Taxes and take-home pay',text:["A $10,000 gross raise does not create $10,000 of additional spendable cash. Payroll taxes, income tax and benefit elections reduce take-home pay. Progressive taxation generally means only income within a higher bracket is taxed at that bracket's marginal rate; crossing a bracket does not cause all earnings to be taxed at the higher rate.",'Use a paycheck or tax calculator after this tool when the decision depends on monthly net cash flow.']},{heading:'Compounding future raises',text:['Because the model applies future percentage hikes to the already-raised salary, an initial increase can have a persistent compounding effect. This is one reason starting salary matters over a career: later percentage increases build from the established base.','The projection assumes the same annual hike every year. Real careers include promotions, freezes, job changes and variable bonuses, so test conservative and strong growth paths.']},{heading:'Negotiation interpretation',text:['A useful negotiation target should be anchored in role scope, demonstrated impact and credible market data. The calculator can show what 5%, 10% or 15% means over time, but it cannot determine what an employer will approve.','If an employer cannot move base salary, quantify alternatives such as a signing bonus, guaranteed bonus, equity, additional leave, remote-work savings or an earlier compensation review.']},{heading:'Common mistakes and limitations',text:['Do not call the projected lifetime gain a guaranteed career gain; it assumes the selected horizon and annual hike rate. Do not confuse real salary with after-tax salary. Do not ignore changes in hours, commute or benefits when comparing jobs. And avoid using an unusually high annual hike indefinitely just because it produces an attractive projection.','Use the result to understand the economic leverage of a raise and to compare scenarios consistently, then pair it with tax and total-compensation analysis.']}]},
"real-return-calculator":{title:'Real Return Calculator',sections:[{heading:'What real return actually measures',text:['Real return measures how quickly purchasing power grows after inflation. A portfolio can show a positive nominal gain while delivering little real progress if prices are rising at nearly the same rate. This calculator therefore answers a different question from a standard compound-growth calculator: not simply how many future dollars you may have, but how much those dollars represent after accounting for inflation.','The implemented formula is the exact Fisher relationship: real rate = (1 + nominal rate) / (1 + inflation rate) - 1. Subtracting inflation from nominal return is a useful approximation at low rates, but the exact formula matters more as either rate becomes larger.']},{heading:'Inputs and outputs on this calculator',text:['Enter the nominal annual return, expected annual inflation, investment amount and time horizon. The calculator compounds the nominal investment at the nominal rate and separately compounds it at the calculated real rate. It reports the real return rate, nominal future value, inflation-adjusted future value, inflation impact and the percentage of nominal future value lost to reduced purchasing power.','The year-by-year table is particularly useful because inflation drag compounds. A small annual gap can look unimportant in year one and become a large difference after twenty or thirty years.']},{heading:'Worked real-return example',text:["Suppose an investment earns 8% while inflation averages 3%. The exact real rate is about 4.85%, not exactly 5%. On $100,000, the nominal value after 20 years is roughly $466,000 under a constant 8% assumption, while the model's real-growth path is roughly $258,000 in today's purchasing-power terms. The gap is not a fee charged by the investment; it represents what inflation does to the spending power of future dollars.","If nominal return falls to 5% while inflation remains 3%, real growth falls to about 1.94%. This illustrates why a portfolio's return should be judged relative to inflation and the investor's required purchasing power, not by the nominal percentage alone."]},{heading:'Nominal dollars versus real dollars',text:["Nominal dollars are the amounts that appear on statements in the future. Real dollars translate those amounts into purchasing-power terms under the inflation assumption. Mixing the two creates misleading comparisons—for example, comparing a future $500,000 balance with today's $300,000 spending goal without inflation adjustment.","For retirement, education and other long-horizon goals, decide whether the target is expressed in today's dollars or future dollars. Then keep contributions, returns and goal amounts on the same basis."]},{heading:'Inflation is not constant',text:['The calculator uses one constant inflation rate for clarity, but actual inflation changes from year to year and differs by household. Housing, healthcare, education, energy and food can move differently from a broad consumer-price index. Someone whose spending is concentrated in a fast-rising category may experience a personal inflation rate above the headline measure.','Run several inflation assumptions rather than treating one forecast as certain. A 2%, 3% and 5% inflation comparison can reveal whether the plan remains viable under materially different purchasing-power environments.']},{heading:'Taxes, fees and return assumptions',text:['The nominal return input is not automatically net of fund expenses, advisory fees or taxes. If you want a spendable real return, use a return assumption that reflects the costs and tax drag relevant to the account. A tax-deferred retirement account, taxable brokerage account and tax-free account can produce different spendable outcomes from the same pre-tax market return.','Historical asset-class returns are not guaranteed future returns. Arithmetic averages can also overstate compounded wealth when returns are volatile; long-run planning is usually better served by defensible geometric or scenario-based assumptions.']},{heading:'Negative and near-zero real returns',text:['A positive nominal return can still produce a negative real return when inflation is higher. For example, 4% nominal growth with 6% inflation gives an exact real return of about -1.89%. The account balance may rise while purchasing power falls.','Near-zero real returns are especially important for cash-like holdings. Their role may still be valid for liquidity and capital stability, but they should not be mistaken for strong long-term purchasing-power growth.']},{heading:'Sequence and volatility limitations',text:['This calculator applies smooth annual rates. Real portfolios experience gains and losses in irregular sequences, and inflation can spike during weak market periods. For an investor withdrawing money, sequence-of-returns risk can materially change sustainability even if the long-run average return ultimately matches the input.','Use this tool for purchasing-power intuition and scenario comparison, not as a full retirement Monte Carlo model or a prediction of a specific investment path.']},{heading:'How to use the result for goals',text:["For a long-term goal, first estimate the future nominal cost or keep the goal in today's dollars. Then compare the real future value with the real goal. If the gap is large, the most controllable responses are usually savings rate, horizon, asset allocation and spending target rather than simply assuming a higher return.",'Recalculate when expected returns, inflation expectations, contributions or the goal horizon changes. The most useful output is often the range across plausible assumptions, not the decimal precision of one scenario.']},{heading:'Common mistakes',text:["Do not subtract inflation twice by entering an already inflation-adjusted return as the nominal return. Do not interpret inflation impact as an actual cash charge. Do not assume that a broad inflation index perfectly represents personal spending. And do not compare a nominal future balance with a goal stated in today's dollars.",'The calculator is strongest when all inputs are expressed consistently and the result is treated as a planning estimate rather than a guaranteed forecast.']}]},
"rsa-key-info":{title:'RSA Key Info',sections:[{heading:'What an RSA key contains',text:['RSA public keys are built from a modulus n and public exponent e. Private keys additionally contain the private exponent d and usually prime factors and CRT parameters used to accelerate private operations. A key-info tool should expose structural metadata without pretending that displaying a key validates its trustworthiness.','Key size normally refers to the bit length of the modulus. A 2048-bit RSA key therefore has a modulus roughly 2048 bits long; it does not mean every field is 2048 bits.']},{heading:'Public versus private material',text:['A public key may be distributed freely for encryption or signature verification. A private key must remain secret because possession enables private-key operations such as signing or decrypting schemes designed for RSA.','Never paste production private keys into an untrusted online service. For sensitive keys, inspect them locally with established cryptographic tooling.']},{heading:'PEM and DER encodings',text:['PEM is Base64-encoded DER wrapped in BEGIN/END labels. DER is the binary ASN.1 representation. Different labels can indicate different structures, such as PUBLIC KEY, RSA PUBLIC KEY, PRIVATE KEY or RSA PRIVATE KEY.','Two PEM files can represent the same mathematical key while using different container formats, so label and ASN.1 structure matter when troubleshooting compatibility.']},{heading:'PKCS#1 and PKCS#8',text:['PKCS#1 defines RSA-specific key structures. PKCS#8 is a general private-key container that can carry RSA and other algorithms; SubjectPublicKeyInfo is commonly used for generic public keys.','Conversion between containers does not create a new RSA key. It changes serialization and metadata around the same key material unless the key is regenerated.']},{heading:'Key size and security',text:['RSA security depends heavily on modulus size and correct implementation. 2048-bit RSA remains a common baseline for many current applications, while smaller legacy keys may be unacceptable under modern policies.','Larger keys increase computational cost and message/signature size. Follow the requirements of the protocol, platform and current security guidance rather than choosing size solely from intuition.']},{heading:'Public exponent',text:['The common public exponent is 65537 because it provides efficient operations while avoiding problems associated with some very small exponent choices when schemes are implemented poorly.','An unusual exponent is not automatically invalid, but it deserves compatibility and policy review.']},{heading:'Encryption padding',text:['Textbook RSA is unsafe. Practical RSA encryption uses a padding/encoding scheme such as OAEP; legacy PKCS#1 v1.5 encryption has different security properties and protocol constraints.','A key inspector cannot tell you whether an application uses RSA safely. Padding choice, error handling, randomness and protocol design are equally important.']},{heading:'Signature padding',text:['RSA signatures use defined encodings such as RSA-PSS or PKCS#1 v1.5 signatures. PSS is probabilistic and includes salt; verification must use matching parameters and hash algorithms.','Do not confuse signing with encrypting a hash using a private key. Standards define the exact encoded structure that implementations must follow.']},{heading:'Certificates and fingerprints',text:['An X.509 certificate contains a public key plus identity, issuer, validity and signature information. A key fingerprint is a digest used to compare key material; it is not the same as a certificate fingerprint unless calculated over the same bytes.','When diagnosing TLS or SSH configuration, compare the exact fingerprint format and object expected by the system.']},{heading:'Safe interpretation',text:['Use this tool to understand key format, modulus size and public metadata. Treat parse failures as format clues rather than proof that a key is cryptographically bad.','For key generation, storage, rotation and validation, rely on maintained cryptographic libraries, HSMs or operating-system tooling and never invent RSA parameters manually.']}]},
"border-radius-gen":{title:'Border Radius Generator',sections:[{heading:'How border-radius works',text:['CSS border-radius rounds an element’s corners. A single value applies to all four corners; two, three or four values follow CSS shorthand rules, and each corner can also be controlled independently.','The radius describes an ellipse at each corner, so horizontal and vertical radii can differ. The slash syntax separates horizontal radii from vertical radii.']},{heading:'Pixels versus percentages',text:['Pixel radii create fixed-size curves. Percentage radii are calculated relative to the box dimensions and are useful for shapes that scale with the element.','A 50% radius on an equal-width-and-height box creates a circle; on a rectangle it produces elliptical ends rather than magically forcing the element square.']},{heading:'Pills and circles',text:['For a pill-shaped button, use a radius at least half the element height, often expressed as a very large value such as 9999px. CSS clamps excessive radii so the ends remain smooth.','For a circle, make width and height equal and use border-radius:50%. Content, padding and borders can change the final box dimensions, so inspect the rendered box.']},{heading:'Per-corner control',text:['The longhand properties are border-top-left-radius, border-top-right-radius, border-bottom-right-radius and border-bottom-left-radius. Independent values are useful for cards attached to edges, speech bubbles and asymmetric panels.','Keep asymmetry intentional. Randomly different radii often look like rendering mistakes rather than a coherent design decision.']},{heading:'Overflow and child content',text:['Rounded corners do not always clip descendants. If images or backgrounds visually escape the curve, overflow:hidden or overflow:clip may be needed, but clipping can also cut shadows, menus and focus rings.','Prefer placing clipping on a dedicated inner wrapper when the outer element needs visible focus or decorative overflow.']},{heading:'Borders and backgrounds',text:['The browser paints backgrounds and borders around the rounded geometry. Thick borders can make the inner curve appear different from the outer curve because the browser computes both edges.','Test high-contrast borders and translucent backgrounds; artifacts that are invisible on a white mockup may become obvious in production themes.']},{heading:'Responsive shapes',text:['A fixed 24px radius may feel very different on a 120px card and a full-width panel. Design systems often define a small set of radius tokens so curvature remains consistent across components.','Use percentages when the shape should track dimensions and tokenized fixed values when visual consistency matters more than proportional geometry.']},{heading:'Browser rendering',text:['Modern browsers support border-radius broadly, so vendor prefixes are normally unnecessary. Small anti-aliasing differences can still appear at fractional dimensions, transforms and high zoom levels.','Avoid chasing one-pixel raster differences unless they affect usability or create a visible seam.']},{heading:'Accessibility',text:['Rounded corners are decorative, but clipping can affect accessibility if it hides focus outlines or text. Ensure keyboard focus remains visible and sufficient target area is preserved.','Do not use shape alone to communicate state; combine it with text, icons or color that meets contrast requirements.']},{heading:'Using generated CSS',text:['Copy the generated declaration into the component or, preferably, map it to a design token if the value will be reused. Check the result with real content, borders, hover states and responsive widths.','The generator gives valid CSS quickly; the final radius should still fit the component hierarchy and the rest of the interface.']}]},
"css-filter-gen":{title:'CSS Filter Generator',sections:[{heading:'What CSS filter changes',text:['The CSS filter property applies graphical operations to an element’s rendered pixels. Common functions include blur(), brightness(), contrast(), grayscale(), hue-rotate(), invert(), opacity(), saturate(), sepia() and drop-shadow().','Filters change presentation, not the underlying image file. Saving or downloading the original asset will not include the CSS effect unless the pixels are rendered into a new image separately.']},{heading:'Function order matters',text:['Multiple filter functions are applied from left to right. Because each operation receives the output of the previous one, changing their order can produce a visibly different result.','Keep the generated order stable when reproducing a look and avoid assuming brightness plus contrast is commutative.']},{heading:'Brightness and contrast',text:['brightness(100%) is the original level; values below darken and values above brighten. contrast(100%) is unchanged, while lower values flatten tonal differences and higher values exaggerate them.','Extreme values can destroy detail in highlights or shadows even though the browser still has the original source pixels.']},{heading:'Saturation, grayscale and sepia',text:['saturate() controls color intensity, grayscale() moves colors toward gray and sepia() adds a warm brown transformation. These functions are useful for hover effects, disabled imagery and visual theming.','Do not rely on grayscale alone to communicate disabled or unavailable state because color perception varies and users still need semantic cues.']},{heading:'Hue rotation',text:['hue-rotate() rotates colors around the hue circle by an angle. It does not simply replace one named color with another, especially for images containing many hues and different saturation/lightness levels.','For precise brand recoloring of icons, SVG fills or purpose-built assets are often more predictable than a filter chain.']},{heading:'Blur',text:['blur() applies a Gaussian-like blur with a CSS length. Blurred pixels can extend beyond the original bounds, which may interact with overflow clipping and stacking.','Large blur values can be expensive on animated or large elements, particularly on lower-powered devices.']},{heading:'Invert and opacity',text:['invert() reverses channel values progressively, while opacity() inside filter changes rendered alpha. CSS also has a separate opacity property; the two can interact differently with filter composition and stacking.','Use the simplest mechanism that achieves the effect, especially when descendants should or should not inherit visual transparency.']},{heading:'Drop shadow',text:['filter:drop-shadow() follows the alpha shape of rendered content, unlike box-shadow which follows the element box. This is useful for transparent PNGs and irregular SVG shapes.','The syntax and rendering differ from box-shadow, so a design copied between the two properties may need adjusted blur and offsets.']},{heading:'Performance and animation',text:['Filters can be animated, but continuously changing blur or complex filter chains may increase GPU/compositing work. Test scrolling and animation on representative devices rather than assuming a smooth desktop preview is sufficient.','Respect prefers-reduced-motion when filters are part of large animated transitions or flashing effects.']},{heading:'Production use',text:['Use the generator to explore a filter chain, then copy the final CSS and test it against actual assets, themes and accessibility states. Keep the source asset available when exact color fidelity matters.','For repeated effects, store the filter string in a class or design token instead of duplicating long chains throughout the codebase.']}]},
'bone-mineral-density-calculator':{title:'Bone Mineral Density Calculator',sections:[{heading:'What bone mineral density means',text:['Bone mineral density (BMD) estimates the mineral content of bone over a measured area. In clinical practice it is usually measured by dual-energy X-ray absorptiometry (DXA), most often at the hip and lumbar spine. A calculator can help interpret entered values or risk factors, but it cannot measure bone density by itself.','Low BMD matters because weaker bone is associated with higher fragility-fracture risk. Fracture risk, however, also depends on age, prior fractures, falls, medications and other clinical factors, so a density result should not be interpreted in isolation.']},{heading:'T-scores and Z-scores',text:['A T-score compares BMD with the average peak bone density of a young healthy reference population and expresses the difference in standard deviations. In postmenopausal women and older men, clinical interpretation commonly uses T-score categories alongside the measurement site and clinical history.','A Z-score compares the result with people of similar age and sex. It is often more informative in younger adults, children and premenopausal women. T-scores and Z-scores answer different questions and should not be substituted for one another.']},{heading:'Common interpretation bands',text:['A T-score at or above -1 is generally described as normal, between -1 and -2.5 as low bone mass or osteopenia, and -2.5 or lower as osteoporosis in the populations for which those criteria apply. A fragility fracture can also materially change clinical assessment regardless of a single numeric threshold.','These cutoffs are diagnostic conventions, not cliffs where bone strength suddenly changes. Risk increases continuously as BMD declines, and treatment decisions can depend on absolute fracture risk rather than the label alone.']},{heading:'Why measurement site matters',text:['Hip, femoral neck and lumbar-spine values can differ. Arthritis, vertebral degeneration, vascular calcification or previous surgery can artifactually elevate some spine readings, while positioning can affect hip measurements.','When following BMD over time, compare the same site and ideally the same facility or compatible machine. Small changes may fall within measurement error and should not automatically be interpreted as true bone gain or loss.']},{heading:'Risk factors beyond density',text:['Age, previous hip or vertebral fracture, parental hip fracture, long-term glucocorticoid use, smoking, heavy alcohol exposure, low body weight and certain inflammatory or endocrine conditions can raise fracture risk independently of BMD.','Falls are also crucial. Balance, vision, medications, footwear, home hazards and muscle strength influence whether low bone density actually results in a fracture.']},{heading:'Calcium, vitamin D and protein',text:['Adequate calcium and vitamin D support bone mineralization, while sufficient protein supports muscle and skeletal tissue. More is not automatically better: supplementation should account for dietary intake, kidney function, medications and clinician advice.','Nutrition is only one part of bone health. Resistance training and appropriately loaded weight-bearing activity can support bone and muscle, while smoking cessation and limiting excessive alcohol reduce avoidable risk.']},{heading:'Medication and secondary causes',text:['Long-term systemic corticosteroids can accelerate bone loss. Other medications and conditions affecting sex hormones, thyroid or parathyroid function, nutrient absorption, kidneys and inflammatory pathways can also contribute to secondary osteoporosis.','Unexpectedly low BMD, fractures at a young age or rapid decline may justify evaluation for secondary causes rather than assuming ordinary age-related loss.']},{heading:'Using the calculator responsibly',text:['Use the tool to understand how the entered density or score is categorized and which risk factors deserve attention. Do not use it to diagnose osteoporosis without an appropriate DXA report and clinical context.','If a result suggests substantial risk, discuss DXA interpretation, fracture history, fall risk and treatment thresholds with a qualified clinician. Emergency evaluation is appropriate for suspected acute fracture after trauma or sudden severe pain.']}]},
"xml-to-json":{title:'XML to JSON',sections:[{heading:'XML and JSON model data differently',text:['XML is a tree of elements with attributes, text nodes, namespaces and ordered children. JSON is built from objects, arrays and primitive values. Conversion is therefore a mapping decision, not a perfectly reversible change of syntax.','Before converting production data, decide how attributes, repeated elements, mixed text and namespaces should appear in JSON.']},{heading:'Elements and objects',text:['A simple XML element such as <name>Karan</name> can map naturally to a JSON property. Nested elements usually become nested objects.','Ambiguity begins when the same child tag appears once in one document and many times in another: consumers need a stable rule for when the JSON value becomes an array.']},{heading:'Attributes',text:['XML attributes have no direct JSON equivalent. Converters often prefix attribute keys, place them in a dedicated object, or merge them with child properties.','Choose one convention and document it; otherwise an attribute named id can collide with a child element also named id.']},{heading:'Repeated elements and arrays',text:['Repeated sibling elements commonly map to arrays. The difficult case is schema consistency: a single <item> may become an object while two items become an array unless the converter is configured to always array certain paths.','APIs should prefer stable output shapes so client code does not branch on object-versus-array at runtime.']},{heading:'Text and mixed content',text:['XML can interleave text with child elements, as in prose containing emphasis tags. Ordinary JSON objects do not preserve that mixed-content model naturally.','If mixed content matters, preserve an ordered node representation rather than flattening everything into one text property.']},{heading:'Namespaces',text:['Namespaces distinguish elements that share local names but belong to different vocabularies. Stripping namespace prefixes can create collisions and lose semantic meaning.','For SOAP, feeds and enterprise XML, decide whether the converted JSON should retain prefix, namespace URI, or a normalized mapping.']},{heading:'Types',text:['XML text is textual unless a schema or application supplies type information. A converter that turns "00123" into number 123 or "false" into Boolean false may unintentionally change identifiers or values.','When fidelity matters, preserve strings or use XSD/schema knowledge to perform intentional type conversion.']},{heading:'Entities and security',text:['XML parsers historically exposed risks such as external entity expansion. Browser-side or server-side conversion should use a parser configuration that does not fetch untrusted external entities.','Do not feed sensitive or untrusted XML to unknown services when local parsing is available.']},{heading:'Round-trip limitations',text:['JSON converted back to XML may not reproduce original attribute order, namespace declarations, whitespace, comments, CDATA boundaries or mixed-content structure.','Treat conversion as data transformation unless the tool explicitly guarantees a lossless node representation.']},{heading:'Using the converter',text:['Use the tool for inspection, API migration and transforming straightforward structured XML. Validate the resulting JSON against expected examples before integrating it into code.','For contractual formats, compare against the XML schema and downstream consumer requirements rather than assuming any generic XML-to-JSON convention is authoritative.']}]},
"http-headers-analyzer":{title:'HTTP Headers Analyzer',sections:[{heading:'What HTTP headers describe',text:['HTTP headers carry metadata about a request or response: content type, caching, authentication, compression, redirects, security policy, cookies and connection behavior. An analyzer helps interpret these fields, but the meaning depends on whether the headers came from the request, final response or an intermediate redirect.','Always record the status code and URL together with the header set. The same header name can have different relevance across response types.']},{heading:'Content-Type',text:['Content-Type tells the client the media type of the response, such as text/html or application/json, and may include a charset. Incorrect values can cause browsers and APIs to parse content incorrectly.','Do not infer type solely from a filename extension. The server’s actual response header is what the client receives.']},{heading:'Caching headers',text:['Cache-Control expresses directives such as max-age, no-cache, no-store, public, private and immutable. Expires is an older date-based mechanism, while Age can show how long a shared-cache response has been stored.','no-cache does not mean “never store”; it means revalidation is required before reuse. no-store is the stronger directive against storage.']},{heading:'Validators',text:['ETag and Last-Modified support conditional requests. Clients can send If-None-Match or If-Modified-Since, allowing a server to return 304 Not Modified instead of the full representation.','Weak and strong ETags have different comparison semantics, so do not strip the W/ prefix when debugging cache behavior.']},{heading:'Compression and negotiation',text:['Content-Encoding identifies transformations such as gzip or br. Accept-Encoding is a request preference. Vary tells caches which request headers can change the selected representation.','A compressed response without appropriate Vary behavior can create cache mistakes when intermediaries serve variants to incompatible clients.']},{heading:'Security headers',text:['Headers such as Content-Security-Policy, Strict-Transport-Security, X-Content-Type-Options and Referrer-Policy can reduce specific browser risks when configured correctly.','Presence alone is not enough: an overly permissive CSP or an HSTS header sent only over an incorrect context may not provide the intended protection.']},{heading:'CORS',text:['Access-Control-Allow-Origin and related CORS headers control whether browsers expose cross-origin responses to frontend JavaScript. CORS is a browser access-control mechanism, not authentication and not a firewall.','Credentials, allowed origins, preflight responses and Vary: Origin need to be considered together.']},{heading:'Cookies',text:['Set-Cookie can include Secure, HttpOnly, SameSite, Domain, Path and lifetime attributes. These flags influence transport, script access and cross-site behavior.','Do not paste live session cookies or authorization headers into public tools. Redact secrets before analysis.']},{heading:'Redirects and proxies',text:['Location identifies redirect targets for 3xx responses. Reverse proxies and CDNs may add or rewrite headers such as Via, X-Forwarded-* or vendor-specific cache diagnostics.','Inspect every redirect hop when a header appears to be missing; the final response may differ from the origin response.']},{heading:'Interpreting results safely',text:['Use the analyzer to spot suspicious or missing metadata, then verify behavior with browser DevTools, curl and authoritative server/CDN documentation.','Headers can reveal infrastructure details and credentials, so sanitize captured output before sharing it in tickets, chat or public bug reports.']}]},
"base64-encoder":{title:'Base64 Encoder',sections:[{heading:'What Base64 is',text:['Base64 is a binary-to-text encoding that represents bytes using a restricted ASCII alphabet. It is useful when binary data must travel through systems designed primarily for text.','Base64 is encoding, not encryption. Anyone who receives the encoded text can decode it without a password or secret key.']},{heading:'How the encoding works',text:['Standard Base64 processes input bytes in 24-bit groups, splits them into four 6-bit values and maps those values to 64 characters. Three input bytes therefore normally become four Base64 characters.','When the final group has fewer than three bytes, padding characters may be added so the output length follows the expected block size.']},{heading:'Size overhead',text:['Because three bytes become four characters, Base64 adds roughly 33% payload overhead before considering surrounding JSON, HTML or transport framing.','Encoding large files inline can therefore increase bandwidth and memory use; object storage or ordinary binary transfer is often better.']},{heading:'Text and character encoding',text:['Text must first become bytes, commonly using UTF-8. Non-ASCII characters may occupy multiple bytes, so Base64 length is based on encoded bytes rather than JavaScript character count.','If two systems use different character encodings before Base64, decoding can produce mojibake even when the Base64 itself is valid.']},{heading:'Padding',text:['Standard Base64 commonly uses = padding at the end. Some protocols omit padding and infer the missing bytes from length.','Do not add or remove padding blindly when working with a protocol; follow that protocol’s exact Base64 variant.']},{heading:'Base64url',text:['Base64url replaces + and / with URL- and filename-friendlier characters - and _. Padding is often omitted. JWT segments use Base64url rather than ordinary padded Base64.','Standard Base64 and Base64url are closely related but not interchangeable without normalization.']},{heading:'Data URLs',text:['Browsers can embed small resources using data URLs such as data:image/png;base64,... . This can be convenient for tiny assets but increases document size and may reduce normal browser caching benefits.','For larger images and downloads, separate resources are usually easier to cache and maintain.']},{heading:'Security misconceptions',text:['Base64 does not hide API keys, passwords or tokens. Encoded secrets remain secrets and should be protected with the same access controls as plaintext values.','Likewise, decoding untrusted Base64 does not make the resulting content safe; validate the decoded bytes before using them as files, HTML or executable data.']},{heading:'Validation and troubleshooting',text:['Valid Base64 uses the expected alphabet, block structure and padding rules for its variant. Line breaks may be accepted in MIME contexts but rejected by stricter decoders.','When decoding fails, check whether the input is Base64url, whether padding was removed, whether whitespace was inserted and whether a data-URL prefix must be stripped first.']},{heading:'Practical use',text:['Use this tool to encode text for testing, inspect Base64 payloads and decode non-sensitive values. For binary files, confirm that the tool handles bytes rather than accidentally treating binary content as text.','For production secrets or private files, prefer trusted local libraries and avoid sending sensitive material to third-party web services.']}]},
"wound-healing-calculator":{title:'Wound Healing Calculator',sections:[{heading:'What this wound estimate represents',text:['This tool estimates healing time from wound size, depth, body location and several host factors. The output is a simplified educational model, not a diagnosis, a promise that a wound will close by a certain date, or a substitute for examination by a clinician. Real healing depends on tissue type, contamination, blood supply, infection, wound care and conditions that cannot be captured by a short form.','The calculator also labels infection risk and suggests a care level. Those labels should be interpreted as model outputs, not clinical clearance to manage a serious wound at home.']},{heading:'How size, depth and location enter the model',text:['The implemented model begins with location-specific baseline days: face 7, scalp 10, torso 14 and extremity 14. It multiplies that baseline by a depth factor of 1 for superficial, 2 for partial-depth and 3.5 for full-depth wounds, then scales further with wound size.','This structure reflects the intuitive fact that deeper and larger wounds usually require more tissue repair. It is still much simpler than clinical wound assessment, which considers length, width, depth, undermining, tissue bed, drainage and perfusion.']},{heading:'Worked model example',text:['Consider a 5 cm partial-depth extremity wound in a younger adult without diabetes, smoking, obesity, immune suppression or poor nutrition. The base location is 14 days; partial depth doubles it, and the size term for 5 cm is 1.5, producing a model estimate around 42 days before additional risk multipliers.','Changing the same wound to full depth raises the depth factor from 2 to 3.5. Adding diabetes multiplies the estimate again by 1.6. This demonstrates why the calculator can change sharply when clinically important risk factors are selected.']},{heading:'Diabetes and blood supply',text:['Diabetes can impair wound healing through vascular disease, neuropathy, immune dysfunction and elevated glucose. Foot wounds are particularly important because loss of protective sensation can allow pressure and trauma to continue unnoticed.','A diabetic wound—especially on the foot, with redness, drainage, odor, black tissue or systemic symptoms—deserves prompt professional assessment. A numeric estimate should never delay care.']},{heading:'Smoking and tissue oxygenation',text:['Smoking is modeled as a 25% time multiplier. Tobacco exposure can reduce tissue oxygen delivery and impair cellular processes needed for repair. The exact effect in an individual cannot be represented by one multiplier, but smoking status is directionally important.','Stopping smoking can support healing and also reduces surgical and cardiovascular risk. The calculator should not be used to infer that a particular number of smoke-free days guarantees a particular healing speed.']},{heading:'BMI, nutrition and immune status',text:['The model increases time for BMI above 30 and more strongly above 35. It also applies a multiplier for moderate or poor nutrition and a large multiplier for immune compromise. These variables are proxies for complex physiology rather than complete assessments.','Adequate energy, protein and micronutrients are important for tissue repair, but routine high-dose supplementation is not automatically appropriate. Nutrition needs depend on wound severity, body size, kidney function and overall health; significant wounds may benefit from individualized dietetic advice.']},{heading:'The phases of healing',text:['Normal healing is commonly described as hemostasis/inflammation, proliferation and remodeling. Inflammation begins early as bleeding is controlled and immune cells clear debris. Proliferation involves granulation tissue, new blood vessels and epithelial coverage. Remodeling can continue for months after the surface appears closed.','The calculator displays simplified phase timing based on its estimated days. Biological phases overlap, so the boundaries should not be read as exact dates.']},{heading:'Infection risk and red flags',text:['The model raises infection risk for diabetes, immune compromise and very high BMI. In practice, infection assessment also depends on wound contamination, foreign material, circulation and local signs. Increasing pain, spreading redness, warmth, swelling, pus, foul odor, fever, red streaking or rapidly worsening appearance warrant medical evaluation.','Deep punctures, bites, burns, wounds with exposed tendon or bone, uncontrolled bleeding, loss of sensation, impaired circulation and wounds that are not progressing should also be assessed professionally.']},{heading:'Wound care principles',text:['Appropriate cleaning, protection from repeated trauma, moisture balance and dressing selection depend on the wound. Many wounds heal better in a controlled moist environment than when repeatedly allowed to dry and crack, but excessive moisture can macerate surrounding skin.','Do not place harsh chemicals into a wound merely to make it feel disinfected; some agents can damage viable tissue. Follow clinician instructions for dressings, debridement and infection management when professional care is indicated.']},{heading:'Why the estimate can be wrong',text:['The formula does not know whether the wound is infected, ischemic, pressure-related, surgical, traumatic or caused by venous disease. It does not measure ankle-brachial pressure, glucose control, edema, medications, wound-bed tissue or bacterial burden. Those omissions can dominate actual healing.','Use serial observation—size, depth, drainage, pain and appearance—rather than relying on the original estimate after the wound changes.']},{heading:'Safe interpretation',text:['A shorter estimate does not mean a wound is harmless, and a longer estimate does not by itself diagnose a complication. The useful role of the calculator is to show how wound depth and host risk factors can change expected difficulty.','For any wound that is deep, infected, worsening, associated with diabetes or poor circulation, or not healing as expected, professional assessment is more important than refining the calculator inputs.']}]},
'fantasy-name-generator':{title:'Fantasy Name Generator',sections:[{heading:'What makes a fantasy name feel coherent',text:['A useful fantasy-name generator does more than concatenate random syllables. Names feel believable when their sound patterns, length, consonant clusters and endings appear to belong to the same imagined language or culture.','The goal is controlled variety: enough randomness to create fresh options while retaining phonetic rules that make the output pronounceable and stylistically consistent.']},{heading:'Sound and syllable structure',text:['Many memorable names alternate consonant and vowel sounds, but fantasy styles may deliberately use clusters such as dr, kh, th or vr. Too many difficult clusters can make a name look exotic while becoming awkward to say aloud.','Read generated names out loud. A name that works visually but repeatedly causes hesitation may be a poor choice for a character readers encounter often.']},{heading:'Prefixes, roots and endings',text:['Generators often combine beginnings, middle syllables and endings. Endings can imply a style: softer vowel endings may feel lyrical, while hard consonants can feel martial or ancient depending on the surrounding sounds.','Avoid assigning rigid gender or species meaning to a suffix unless that convention is intentional in your world. Internal consistency is more valuable than copying stereotypes from existing fantasy franchises.']},{heading:'Character versus place names',text:['A personal name usually needs to be easy to distinguish in dialogue and narration. Place names can tolerate different rhythms, compounds or descriptive roots because they function as geographic labels.','If the tool offers categories, use them as creative prompts rather than strict linguistic rules. A strong world can deliberately reuse roots across people, cities and regions to suggest shared history.']},{heading:'Avoid accidental collisions',text:['Search important generated names before publishing. A random output can accidentally match a real person, company, medication, slur, famous fictional character or protected franchise term.','For commercial projects, collision checking matters more for central characters, game titles and brands than for incidental background names.']},{heading:'Build naming families',text:['Once you find one strong name, use its sound pattern to create relatives, dynasties or regional variants. Repeated roots can imply ancestry, while systematic vowel or suffix changes can distinguish generations or dialects.','This approach turns a random generator into a world-building seed rather than a one-off novelty tool.']},{heading:'Improve readability in a cast',text:['Avoid giving several major characters names with the same first letter, length and rhythm. Readers identify names partly by visual shape, so contrast can reduce confusion.','A cast containing Aralen, Aralin and Aralon may be internally consistent but unnecessarily difficult to track. Preserve cultural coherence while giving principal characters distinct silhouettes.']},{heading:'Using generated names creatively',text:['Generate a larger pool than you need, shortlist the options that match the character or setting, then edit spelling and pronunciation deliberately. Random output is a starting point, not an obligation.','Keep notes on pronunciation, meaning and naming conventions if the project grows. Consistency across later chapters, campaigns or game content will matter more than the exact random seed that produced the first name.']}]},
'css-animation-gen':{title:'CSS Animation Generator',sections:[{heading:'How CSS animation works',text:['CSS animations combine an @keyframes rule with animation properties applied to an element. Keyframes define states over time; duration, timing function, delay, iteration count and direction determine how the browser travels through those states.','A generator is most useful when it exposes those controls and produces editable CSS rather than hiding the underlying syntax.']},{heading:'Keyframes and percentages',text:['The simplest animation uses from and to, equivalent to 0% and 100%. Intermediate percentages let you create pauses, overshoot, multi-stage transforms or opacity changes within one cycle.','Keep keyframes focused. If unrelated properties change independently, separate animations can be easier to maintain and tune.']},{heading:'Duration and delay',text:['Duration controls the time for one cycle. Very short durations can feel abrupt; long durations can make interfaces feel sluggish. Delay postpones the start and can be negative, which starts the animation partway through its timeline.',"For interface feedback, timing should support the user's task rather than showcase motion for its own sake."]},{heading:'Timing functions',text:['linear moves through progress at a constant rate. ease, ease-in and ease-out change acceleration, while cubic-bezier() allows custom curves. steps() is useful for sprite sheets, counters and deliberately discrete motion.','The timing curve changes perceived motion even when duration is identical, so preview it with the actual distance and property being animated.']},{heading:'Transforms and performance',text:['transform and opacity are generally good animation targets because browsers can often composite them without repeatedly recalculating document layout. Animating width, height, top or left may trigger more layout and paint work.','Performance still depends on element size, effects, device capability and how many elements animate simultaneously. Test on realistic mobile hardware when motion is prominent.']},{heading:'Iteration and direction',text:['iteration-count can be a number or infinite. direction values such as alternate and alternate-reverse can remove the visual jump that occurs when an animation resets to its first frame.','Infinite decorative motion should be used sparingly because it consumes attention and can increase rendering work.']},{heading:'Fill mode and final state',text:['animation-fill-mode controls whether keyframe styles apply before or after execution. forwards preserves the final keyframe appearance, while backwards can apply the starting keyframe during a delay.','Remember that fill mode affects presentation, not application state. Interactive components should not rely on animation alone to represent durable logical state.']},{heading:'Accessibility and reduced motion',text:['Respect the prefers-reduced-motion media query. Users may request less animation because of vestibular disorders, distraction or personal preference.','A reduced-motion mode can remove nonessential movement, shorten transitions or replace large transforms with subtle opacity changes while preserving information and functionality.']},{heading:'Production checklist',text:['Copy the generated @keyframes and animation declaration, verify class names and vendor requirements for your supported browsers, and test start, interruption and repeated triggering.','Also check layout at different viewport sizes: a transform distance that looks correct on desktop can move content off-screen on a narrow device.']}]},
'api-response-time':{title:'API Response Time Calculator',sections:[{heading:'What response time measures',text:['API response time is the elapsed time between a client initiating a request and receiving the relevant response. Depending on the measurement point, it can include DNS, connection setup, TLS, network travel, queueing, server processing and response transfer.','Define the boundary before comparing numbers. Server processing time from application logs is not the same metric as end-to-end latency measured by a browser or remote client.']},{heading:'Latency percentiles',text:['Average latency can hide a poor user experience. p50 describes the median, while p95 and p99 expose slower tail requests that often matter during load spikes or dependency failures.','Track percentiles over meaningful windows and by endpoint. Combining a fast health check with a slow reporting endpoint can produce an average that describes neither workload well.']},{heading:'Throughput and concurrency',text:['Requests per second measures throughput, not speed. A service can sustain high throughput while individual requests are slow if many execute concurrently.','As utilization approaches a bottleneck, queueing can increase latency sharply. Load testing should therefore increase concurrency gradually and observe both throughput and percentile latency.']},{heading:'Network components',text:['DNS lookup, TCP establishment, TLS negotiation and geographic round trips can dominate short API calls. Connection reuse and HTTP/2 or HTTP/3 can reduce some setup overhead.','Measure from locations representative of users. A backend benchmark inside the same data center cannot predict internet latency for distant clients.']},{heading:'Server processing',text:['Application time can include authentication, serialization, database queries, cache misses, external APIs and CPU work. Distributed tracing helps split total latency across those stages.','Optimize the actual bottleneck rather than guessing. A faster JSON serializer will not solve an endpoint spending most of its time waiting on an unindexed database query.']},{heading:'Payload size',text:['Large request and response bodies increase transfer and serialization time, particularly on slow or high-latency connections. Compression can reduce text payload size at the cost of CPU.','Pagination, field selection and appropriate media formats often improve both latency and bandwidth more sustainably than micro-optimizing application code.']},{heading:'Cold starts and caches',text:['Serverless cold starts, empty caches and first database connections can create occasional high latency. Warm benchmarks may therefore understate what users experience after idle periods or deployments.','Record cold and warm behavior separately, and avoid treating cache-hit performance as representative when the production hit rate is unknown.']},{heading:'Timeouts and budgets',text:['A latency budget assigns portions of an end-to-end target to gateways, application work, databases and downstream services. Timeouts should reflect that budget and prevent one dependency from consuming the entire request window.','Retries can improve reliability for transient failures but may amplify load. Use bounded retries, backoff and idempotency where appropriate.']},{heading:'Using the calculator',text:['Enter measurements from the same definition and test context, then use the output to compare endpoints or scenarios. Repeated samples are more informative than a single request.','For production SLOs, pair response time with error rate, traffic and saturation metrics so a seemingly fast service is not considered healthy while returning failures.']}]},
'curl-builder':{title:'cURL Command Builder',sections:[{heading:'What cURL represents',text:['cURL is a command-line client for transferring data with URLs. It is widely used to reproduce HTTP requests, test APIs, inspect headers and create examples that developers can run outside a browser.','A command builder should make the request explicit: method, URL, headers, query parameters, authentication and body should be visible so the generated command is understandable and editable.']},{heading:'HTTP methods',text:['GET usually retrieves a resource, POST commonly creates or submits data, PUT replaces a representation, PATCH applies a partial update and DELETE requests removal. APIs can define semantics differently, so follow the target API contract.','cURL may infer POST when data is supplied, but explicitly setting the intended method can make generated examples clearer.']},{heading:'Headers',text:['Use -H or --header for fields such as Accept, Content-Type, Authorization and custom API headers. Content-Type describes the request body format, while Accept expresses the response formats the client prefers.','Do not add browser headers mechanically. Most API tests need only headers that affect authentication, negotiation or application behavior.']},{heading:'JSON request bodies',text:['JSON can be sent with --data or --data-raw and an application/json Content-Type. Shell quoting matters: single quotes are convenient on many Unix shells but behave differently in Windows command environments.','Validate generated JSON independently when a request fails. A syntactically valid cURL command can still contain invalid application data.']},{heading:'Query parameters and encoding',text:['Query parameters belong in the URL and should be percent-encoded when values contain spaces or reserved characters. cURL options such as --get and --data-urlencode can help construct encoded query strings.','Avoid manually concatenating untrusted values into commands because shell metacharacters can change command behavior.']},{heading:'Authentication',text:['Bearer tokens are commonly sent in the Authorization header; basic authentication can use --user; client certificates and other schemes require different options.','Generated commands containing secrets should be treated as sensitive. Avoid committing API keys, tokens, cookies or passwords to source control, chat logs or shell history.']},{heading:'Inspecting the response',text:['-i includes response headers, -v shows verbose connection details, and -I requests headers only where appropriate. -o can save the body to a file, while -w can print timing and status metadata.','Verbose output may expose credentials in headers, so sanitize logs before sharing them.']},{heading:'Redirects, TLS and proxies',text:['-L follows redirects. Proxy and certificate options can be useful for debugging, but disabling TLS verification with -k removes an important security check and should not become a production workaround.','If certificate validation fails, fix the trust chain, hostname or environment rather than normalizing insecure commands.']},{heading:'Using generated commands safely',text:['Review the final URL, method and body before running commands that create, update or delete data. Test against non-production environments when possible.','Use the builder as a transparent request composer, then consult the API documentation for required fields, rate limits, idempotency behavior and authentication rules.']}]},
'network-speed-test':{title:'Network Speed Test',sections:[{heading:'What a speed test measures',text:['A network speed test estimates how quickly data can move between your device and a selected test server. Typical outputs include download throughput, upload throughput and latency, but each describes a different aspect of connection quality.','The result is a snapshot of one path at one time. It is not necessarily the maximum capacity of the access plan or the speed to every website and service.']},{heading:'Download and upload throughput',text:['Download speed measures data received by the device, while upload speed measures data sent. Values are commonly reported in megabits per second (Mbps), not megabytes per second (MB/s). Eight bits equal one byte before protocol overhead.','Streaming and browsing are often download-heavy; cloud backup, video calls and content creation can depend more heavily on upload capacity.']},{heading:'Latency and ping',text:['Latency measures delay rather than bandwidth. A connection can have hundreds of Mbps yet still feel poor in gaming or calls if round-trip latency is high.','Geographic distance, routing, Wi-Fi contention and queueing all influence latency. Test to both nearby and application-relevant servers when diagnosing a problem.']},{heading:'Jitter and packet loss',text:['Jitter describes variation in packet delay. Real-time voice and video can suffer when packets arrive irregularly even if average latency is acceptable.','Packet loss forces retransmission for reliable protocols and can create glitches for real-time traffic. Persistent loss often indicates congestion, wireless interference, cabling or upstream network problems.']},{heading:'Wi-Fi versus wired tests',text:['Wi-Fi performance depends on signal strength, channel congestion, frequency band, access-point capability and device radios. A wired Ethernet test can help separate local wireless limitations from the internet service itself.','For a fair ISP comparison, test near the router or by cable before concluding that the broadband line is underperforming.']},{heading:'Server selection',text:['A nearby test server often produces lower latency and can reveal local access capacity. A distant server includes more internet routing and may better resemble a remote application.','Different test providers and servers can therefore return different but valid results. Record the server and test method when comparing runs.']},{heading:'Background traffic',text:['Cloud sync, software updates, streaming, VPN traffic and other household users consume bandwidth during a test. Pause avoidable transfers when measuring line capacity, but also test under normal household load if the goal is to understand everyday experience.','Multiple simultaneous devices can reveal bufferbloat or router limitations that an isolated test misses.']},{heading:'Repeatable testing',text:['Run several tests at different times of day using the same device and connection method. Median or typical results are more useful than selecting the single fastest run.','If performance degrades predictably during busy evening periods, record those results before contacting the provider.']},{heading:'Interpreting the result',text:["Compare measured throughput with the service tier while allowing for protocol overhead, Wi-Fi limits and provider wording such as 'up to.' Also compare latency, loss and stability with the requirements of the applications you actually use.",'When troubleshooting, change one variable at a time: cable versus Wi-Fi, VPN on versus off, different server, router reboot, or direct modem connection where safe and supported.']}]},
'text-diff-inline':{title:'Inline Text Diff',sections:[{heading:'What an inline diff does',text:['An inline text diff compares two text versions and highlights additions, deletions and sometimes replacements within the same flow. It is useful for proofreading, configuration review, generated output and understanding small edits without manually scanning entire documents.','The result depends on how the algorithm tokenizes input and aligns sequences, so a highlighted replacement is an interpretation of change rather than semantic understanding.']},{heading:'Character, word and line granularity',text:['Character-level diffs expose tiny spelling changes but can become noisy. Word-level diffs are easier for prose, while line-level diffs work well for source files and structured text.','Choose the granularity that matches the task. A one-character change in an identifier can be critical in code even when a word-level view looks simple.']},{heading:'Insertions and deletions',text:['Diff algorithms usually model change as insertions and deletions. A replacement may therefore appear as one deleted token followed by one inserted token.','Do not assume highlighted order means the author literally performed edits in that sequence; the diff reconstructs a minimal or near-minimal transformation between two final strings.']},{heading:'Whitespace',text:['Spaces, tabs and line endings can create differences that are visually subtle. Some tools ignore whitespace while others treat every character as significant.','For code, YAML and other whitespace-sensitive formats, ignoring whitespace can hide meaningful changes. For prose, an ignore-whitespace option can reduce noise.']},{heading:'Case and punctuation',text:['Case-sensitive comparison distinguishes Value from value. Punctuation can also alter token boundaries and produce larger highlighted regions than expected.','Normalize only when the comparison goal permits it. A case-insensitive diff is useful for editorial review but inappropriate for many identifiers and data formats.']},{heading:'Moved text',text:['Basic sequence diff algorithms often represent moved paragraphs as a deletion at the old location and insertion at the new one. Detecting moves requires additional heuristics.','When a document has been heavily reordered, combine inline diff with side-by-side or structural comparison to understand the edit more clearly.']},{heading:'Large documents',text:['Very large inputs can require more CPU and memory because sequence alignment becomes expensive. Breaking a comparison into logical sections can improve readability and performance.','For source repositories, specialized version-control diff tools may provide syntax-aware context, rename detection and history that a browser text comparator does not.']},{heading:'Sensitive text',text:['Text pasted into a comparison tool may contain credentials, contracts, personal data or proprietary code. Prefer local processing for sensitive material and understand whether the tool transmits content to a server.','Redact secrets before sharing screenshots or diff output because deleted text can remain visible in the comparison.']},{heading:'Using the diff result',text:['Review highlighted changes in context rather than accepting them mechanically. A small textual edit can create a large semantic change, while a large formatting diff can leave meaning unchanged.','For important documents or code, use the diff as a review aid alongside tests, validation or domain-specific checks.']}]},
'erectile-dysfunction-risk-calculator':{title:'Erectile Dysfunction Risk Calculator',sections:[{heading:'What an ED risk calculator can do',text:['Erectile dysfunction (ED) is persistent difficulty achieving or maintaining an erection sufficient for satisfactory sexual activity. A risk calculator can organize common contributing factors, but it cannot diagnose ED or identify the cause from a score alone.','Erections depend on vascular, neurologic, hormonal and psychological systems. Because those systems overlap with general health, ED can sometimes be an early reason to evaluate cardiovascular and metabolic risk.']},{heading:'Age and vascular health',text:['ED becomes more common with age, but it is not an inevitable consequence of getting older. Blood-vessel function, medications, diabetes, smoking and cardiovascular disease often explain more than age itself.','New or progressive ED deserves context, particularly when accompanied by chest symptoms, exercise intolerance or multiple cardiovascular risk factors.']},{heading:'Diabetes and blood pressure',text:['Diabetes can affect blood vessels and nerves involved in erection, especially when glucose exposure is prolonged. Hypertension can also impair vascular function, and some blood-pressure medications may influence sexual function.','Do not stop prescribed medication because of a calculator result. A clinician can review alternatives when a medication appears temporally related to symptoms.']},{heading:'Smoking, alcohol and activity',text:['Smoking damages vascular function and is a modifiable ED risk factor. Heavy alcohol use can impair sexual response and contribute to hormonal, neurologic or relationship problems.','Regular physical activity supports cardiovascular health and may reduce risk, but exercise is not a guaranteed treatment for every cause of ED.']},{heading:'Weight and metabolic factors',text:['Obesity, dyslipidemia and metabolic syndrome are associated with vascular and hormonal pathways relevant to erectile function. Waist circumference and cardiometabolic health can provide context beyond body weight alone.','Weight change should be approached as a broader health goal rather than assuming a specific number of kilograms will produce a predictable erectile response.']},{heading:'Psychological and relationship factors',text:['Anxiety, depression, stress, relationship conflict and performance concerns can cause or worsen ED. Psychological contributors can coexist with vascular or hormonal factors rather than being mutually exclusive.','Situational symptoms, preserved spontaneous erections and changes linked to stress can provide clues, but they do not replace professional assessment.']},{heading:'Hormones and medications',text:['Low testosterone can contribute to reduced libido and sometimes erectile symptoms, but ED is not a reliable standalone test for testosterone deficiency. Diagnosis requires appropriate symptoms and properly timed laboratory evaluation.','Antidepressants, certain antihypertensives, opioids and other medicines can affect sexual function. Review the complete medication and supplement list with a clinician rather than making unsupervised changes.']},{heading:'When evaluation matters',text:['Persistent ED can justify assessment of blood pressure, diabetes risk, lipids, medication effects and other relevant conditions. Sudden onset after injury, penile pain or deformity, neurologic symptoms, or other concerning changes may require more targeted evaluation.','Seek urgent care for an erection lasting about four hours or longer, especially if painful, because priapism can damage tissue.']},{heading:'Interpreting the score',text:["Treat the tool's result as a risk-factor summary, not a percentage probability that you have ED and not a severity scale comparable with validated questionnaires unless the implementation explicitly uses one.",'If symptoms are persistent or distressing, a healthcare professional can distinguish vascular, medication-related, hormonal and psychological contributors and discuss evidence-based treatment options.']}]},
}
export function CalculatorBatch49DeepDive({slug}:{slug:string}){const g=guides[slug];if(!g)return null;return <section className="mx-auto max-w-5xl px-4 py-10"><div className="rounded-2xl border border-gray-200 bg-white p-6 md:p-8"><h2 className="text-2xl md:text-3xl font-bold text-gray-900">{g.title}: Detailed Guide</h2><p className="mt-3 text-gray-700 leading-7">Explore the inputs, formulas, assumptions, scenarios, costs, thresholds, limitations and practical interpretation behind this specific tool.</p><div className="mt-8 space-y-8">{g.sections.map((s,i)=><article key={i}><h3 className="text-xl font-semibold text-gray-900">{s.heading}</h3>{s.text.map((p,j)=><p key={j} className="mt-3 text-gray-700 leading-7">{p}</p>)}</article>)}</div></div></section>}